//
// Global styling
//

// To be decided if we want CSS Custom Properties out of these.
@tinymce-border-color: @border-color;
@tinymce-border-radius: 10px;
@tinymce-border-width: 2px;
@tinymce-box-shadow: none;

@tinymce-separator-color: darken(@border-color, 4.5%); // created global Custom Property as this is used in multiple different components

@editor-header-inline-background-color: @background-color;

.tox {
  color: var(--tox-private-color-black, @color-black);
  font-family: var(--tox-private-font-stack, @font-stack);
  font-size: var(--tox-private-font-size-base, @font-size-base);
}

.tox-tinymce {
  border: @tinymce-border-width solid @tinymce-border-color;
  border-radius: @tinymce-border-radius;
  box-shadow: @tinymce-box-shadow;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  font-family: var(--tox-private-font-stack, @font-stack);
  overflow: hidden;
  position: relative;
  visibility: inherit !important;
}

// Place the border/shadow on the header in inline mode instead of the root component
.tox.tox-tinymce-inline {
  border: none;
  box-shadow: none;
  overflow: initial;

  .tox-editor-container {
    overflow: initial;
  }

  .tox-editor-header {
    background-color: @editor-header-inline-background-color;
    border: @tinymce-border-width solid @tinymce-border-color;
    border-radius: @tinymce-border-radius;
    box-shadow: @tinymce-box-shadow;
    overflow: hidden;
  }
}

.tox-tinymce-aux {
  font-family: var(--tox-private-font-stack, @font-stack);
  z-index: var(--tox-private-z-index-sink, @z-index-sink);
}

// RTL
.tox[dir="rtl"] {
  // Rotates configured icons 180 degrees when rendering in RTL
  .tox-icon--flip svg {
    transform: rotateY(180deg);
  }
}

/**
 * TinyMCE components picker plugin.
 * Provides a dialog for browsing and inserting pantoken components.
 *
 * \@module
 */
import type { Editor } from "tinymce";
import type { CdnFile } from "@pantoken/cdn";
import customComponentsModel from "@pantoken/plugin-custom-components/model.json" with { type: "json" };
import { resolveExampleTargets } from "@pantoken/utils/example-targets";
import type { CssDocEntry } from "../cssdoc/model.js";
import type { MissingAssetHandler } from "../types.js";
import { trackAndInjectAsset } from "../content-css.js";
import { insertHtml } from "../lib/insertion-target.js";
import { registerComponentModifierToolbar } from "../lib/component-modifier-toolbar.js";
import { getEditorStrings } from "../strings.js";

/**
 * Configuration options for the components picker plugin.
 */
export interface ComponentsPickerOptions {
  model: CssDocEntry[];
  currentAssets: CdnFile[];
  onMissingAsset?: MissingAssetHandler;
  /** Resolve a component's CSS file to a local or CDN URL. Defaults to the default CDN provider. */
  buildAssetUrl?: (file: CdnFile) => string;
  /** Register this picker's standalone toolbar button and menu item. */
  registerUi?: boolean;
  /** Evaluated each time the picker opens, without changing existing editor content. */
  isAvailable?: (entry: CssDocEntry) => boolean;
  /** Read at insertion time to select the matching Canvas example. Defaults to enabled. */
  includeInteractions?: () => boolean;
}

/** Command that opens the components picker. */
export const COMPONENTS_COMMAND = "pantokenOpenComponents";

/**
 * A component/utility record for display in the picker.
 */
interface ComponentRecord {
  name: string;
  className: string;
  kind: "component" | "utility" | "custom-component";
  description?: string;
  examples: string[];
}

const COMPONENT_PICKER_EXCLUDED_COMPONENTS = new Set([
  "agent-shell",
  "date-input",
  "date-time-input",
  "drawer-layout",
  "file-drop",
  "form-field",
  "form-field-messages",
  "in-place-edit",
  "input-group",
  "number-input",
  "range-input",
  "side-nav-bar",
  "simple-select",
  "text-area",
  "text-input",
  "tray",
]);

const customComponentNames = new Set(customComponentsModel.map((entry) => entry.name));

function normalizeExample(example: string): string {
  const fencedHtml = example.match(/```(?:html(?:\s+-[a-z][a-z0-9-]*)*)?\s*\r?\n([\s\S]*?)```/iu);
  const markup = fencedHtml?.[1] ?? example.replace(/^(?:\s*-[a-z][a-z0-9-]*\s*)+\r?\n/u, "");
  return markup.trim();
}

/**
 * Create the components picker plugin factory.
 * Returns a function suitable for `tinymce.PluginManager.add()`.
 *
 * Usage:
 *   tinymce.PluginManager.add(
 *     "pantokenComponents",
 *     createComponentsPlugin(`{ model, currentAssets, onMissingAsset }`)
 *   );
 */
export function createComponentsPlugin(options: ComponentsPickerOptions): (editor: Editor) => void {
  // TinyMCE always instantiates plugins with `new Plugin(editor, ...)` — must be a constructible
  // function expression, not an arrow function (arrows throw "is not a constructor").
  return function pantokenComponentsPlugin(editor: Editor) {
    const strings = getEditorStrings(editor);
    // Build a list of available components.
    const openDialog = (): void =>
      openComponentsDialog(
        editor,
        buildComponentList(options.model.filter((entry) => options.isAvailable?.(entry) ?? true)),
        options,
      );
    registerComponentModifierToolbar(editor, options.model);

    if (options.registerUi === false) {
      editor.addCommand(COMPONENTS_COMMAND, openDialog);
      return;
    }

    // Register the toolbar button.
    editor.ui.registry.addButton("pantokenComponents", {
      text: strings.componentsToolbarText,
      tooltip: strings.componentsToolbarTooltip,
      onAction: openDialog,
    });

    // Register a menu item.
    editor.ui.registry.addMenuItem("pantokenComponents", {
      text: strings.componentsMenuText,
      onAction: openDialog,
    });
  };
}

/**
 * Build a list of components for the picker.
 */
function buildComponentList(model: CssDocEntry[]): ComponentRecord[] {
  const list: ComponentRecord[] = [];

  for (const entry of model) {
    const kind = entry.kind as string;
    if (kind !== "component" && kind !== "custom-component") continue;
    if (COMPONENT_PICKER_EXCLUDED_COMPONENTS.has(entry.name)) continue;

    list.push({
      name: entry.name,
      className: entry.className,
      kind: entry.kind as any,
      description: (entry as any).description || "",
      examples: (entry as any).examples || [],
    });
  }

  return list.sort((a, b) => a.name.localeCompare(b.name));
}

/**
 * Open the components picker dialog.
 */
function openComponentsDialog(
  editor: Editor,
  components: ComponentRecord[],
  options: ComponentsPickerOptions,
): void {
  const strings = getEditorStrings(editor);
  // Dialog body: title and results list.
  const _body = editor.windowManager.open({
    title: strings.componentsDialogTitle,
    body: {
      type: "panel",
      items: [
        {
          type: "listbox",
          name: "component",
          label: strings.componentsListLabel,
          items: components.map((c) => ({
            text: c.name,
            value: c.name,
          })),
          size: 10,
        } as any,
      ],
    },
    buttons: [
      {
        text: strings.insertButton,
        type: "submit",
        primary: true,
        enabled: components.length > 0,
      },
      {
        text: strings.cancelButton,
        type: "cancel",
      },
    ],
    onSubmit: (api: any) => {
      const data = api.getData() as { component: string };
      const selectedName = data.component;
      const component = components.find((c) => c.name === selectedName);

      if (component) {
        const exampleIndex = resolveExampleTargets(component.examples, {
          interactions: options.includeInteractions?.() ?? true,
        }).canvasRce[0];
        if (exampleIndex === undefined) {
          api.close();
          return;
        }
        const html = normalizeExample(component.examples[exampleIndex]);
        insertHtml(editor, html);

        // If this component has a CSS file, inject it into the content area.
        const cssFile: CdnFile = {
          package:
            component.kind === "custom-component" || customComponentNames.has(component.name)
              ? "@pantoken/plugin-custom-components"
              : "@pantoken/components",
          path: `dist/${component.name}.css`,
        };
        trackAndInjectAsset(editor, cssFile, options);
      }

      api.close();
    },
  });
}

/**
 * Script fonts for the social-card renderer (`docs/scripts/gen-og.ts`).
 *
 * The card's brand face — Atkinson Hyperlegible Next — is vendored under `docs/assets/fonts`, but it
 * only covers Latin. Rendering a card for every locale needs a face per non-Latin script, and the
 * Noto family that covers them all is far too large to commit (~53 MB of variable TTFs). So they're
 * fetched once into a git-ignored cache under `docs/assets/fonts/noto/`, from a pinned `google/fonts`
 * commit, and each download is checked against a recorded SHA-256 before it's used. A cached file is
 * reused as-is, so only the first `docs:assets` run on a machine (or a cold CI runner) pays for it.
 *
 * `resvg` reads TTF/OTF, and `google/fonts` now ships Noto only as variable TTFs. `resvg` renders the
 * default instance of a variable font rather than instancing the `wght` axis, so non-Latin cards come
 * out at regular weight — acceptable for a social card, and the alternative (static instances) is no
 * longer published upstream.
 *
 * @module
 */
import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

/** The `google/fonts` commit every font below is pinned to. */
const PIN = "205859f680703e449fe05dce0f792cc041d6dc89";

/** A downloadable script font: where to get it, what it's called, and what it must hash to. */
interface NotoFont {
  /** The path under `ofl/` in `google/fonts`, URL-encoded. */
  path: string;
  /** The `font-family` name to reference it by in the SVG. */
  family: string;
  /** SHA-256 of the file at {@link PIN}. */
  sha256: string;
  /** Han, kana, and Hangul advance about one em per glyph rather than the Latin half-em. */
  ideographic?: boolean;
  /** Han and kana run without spaces, so lines have to break between characters. */
  wrapByCharacter?: boolean;
  /**
   * Whether the card should thicken this face's strokes. `resvg` renders a variable font's default
   * instance and ignores `font-weight`, and a few scripts come out too light against the navy field
   * at that weight, so their text is stroked in its own fill colour to fake the missing weight.
   */
  syntheticBold?: boolean;
}

const NOTO_FONTS = {
  sans: {
    path: "notosans/NotoSans%5Bwdth,wght%5D.ttf",
    family: "Noto Sans",
    sha256: "bfb7bb691513f12e734dc346c03a03f784912432d7e3fa8e56efcf906fe86b3d",
    syntheticBold: true,
  },
  arabic: {
    path: "notosansarabic/NotoSansArabic%5Bwdth,wght%5D.ttf",
    family: "Noto Sans Arabic",
    sha256: "63111b5b2e074dd48cc67692e0a2726d86ee94c1c37fe8598257b7b4e87e869e",
  },
  hebrew: {
    path: "notosanshebrew/NotoSansHebrew%5Bwdth,wght%5D.ttf",
    family: "Noto Sans Hebrew",
    sha256: "7ef36a2c3593758cdb622e1bdef4f84523e92fbc3ccc667438dd80ff54c2de88",
    syntheticBold: true,
  },
  devanagari: {
    path: "notosansdevanagari/NotoSansDevanagari%5Bwdth,wght%5D.ttf",
    family: "Noto Sans Devanagari",
    sha256: "9ce7b04f60e363d8870e5997744cf85cf69d38a4d7d129d364d92a3b14b461d7",
  },
  armenian: {
    path: "notosansarmenian/NotoSansArmenian%5Bwdth,wght%5D.ttf",
    family: "Noto Sans Armenian",
    sha256: "0870908d8318435a5daf1cd280ae15063f990cd9ad60f3e94c734ce9e1ffef71",
  },
  thai: {
    path: "notosansthai/NotoSansThai%5Bwdth,wght%5D.ttf",
    family: "Noto Sans Thai",
    sha256: "5a1c559bb539583c8a1fd99d1c5b9491e5e14478c9cd2bd0970d5c3096cc9ef8",
  },
  japanese: {
    path: "notosansjp/NotoSansJP%5Bwght%5D.ttf",
